{
  "title": "Supportive Care Medication Frequency in Pediatric Bronchiolitis",
  "subtitle": "Albuterol exposure rates across formulations (MedCP EHR cohort)",
  "summary": "Among children ≤18 years with a bronchiolitis diagnosis, **albuterol** (a short-acting β2-agonist used off-label for wheezing) appears in multiple formulations. This analysis quantifies exposure frequency across the MedCP EHR database.\n\nThe most frequently prescribed formulation among this cohort is the **Metered Dose Inhaler (MDI)** at 0.09 MG/ACTUAT, followed by **inhalation solutions** for nebulized delivery.",
  "panels": [
    {
      "title": "Albuterol Formulation Exposure Count",
      "caption": "Number of albuterol exposure events across pediatric bronchiolitis patients (≤18 years)",
      "notes": "Formulation names truncated for readability. MDI = Metered Dose Inhaler; NDA020503 references a branded HFA-134a albuterol formulation approved under an abbreviated new drug application.",
      "figure": {
        "tool": "show_chart",
        "params": {
          "type": "bar",
          "title": "Albuterol Exposure Count by Formulation (Pediatric Bronchiolitis)",
          "labels": [
            "Albuterol Inhal Soln 5 MG/ml (Nebulizer)",
            "MDI Albuterol 0.09 MG/ACT NDA020503",
            "Albuterol / Ipratropium Soln Nebulizer",
            "MDI Albuterol 0.09 MG/ACT Meters Dose",
            "Albuterol Inhalation Solution Generic",
            "Levalbuterol Inhal Soln Concentrate",
            "Albuterol/Ipratropium Neb Soln Combo",
            "DuoNeb Albuterol/Ipratropium MDI",
            "Levalbuterol Nebulizer Concentrate (Lever)",
            "Albuterol Oral Tablet 4 MG/12 HR"
          ],
          "datasets": [
            {
              "label": "Exposure Count",
              "data": [630208, 351137, 245314, 197318, 164956, 143770, 119022, 136696, 954, 1],
              "backgroundColor": "#0d6efd"
            }
          ]
        }
      }
    },
    {
      "title": "Patient-Level Counts",
      "caption": "Unique patient counts who received albuterol for bronchiolitis (≤18 years)",
      "notes": "Some pediatric patients may have both MDI and nebulized prescriptions depending on severity of symptoms and clinical setting.",
      "figure": {
        "tool": "show_chart",
        "params": {
          "type": "bar",
          "title": "Unique Patients Prescribed Albuterol for Bronchiolitis (≤18 Years) by Formulation",
          "labels": [
            "NDA020503 MDI (Branded HFA)",
            "Generic MDI 0.09 MG/ACT",
            "Alb/Ipratropium Neb Soln Combo",
            "Albuterol/Solvne Inhal Soln Gen",
            "Levalbuterol Inhal Soln Conc",
            "DuoNeb Albut/Iprat Nebulizer",
            "Levalbuterol Neb Concentrate",
            "Alb 5 MG/ml Neb Soln",
            "Alb IV/Oral Table 4 MG/12 HR",
            "Sensor MDI (with Sensitve)"
          ],
          "datasets": [
            {
              "label": "Unique Patients",
              "data": [31694, 8333, 1531, 15312, 527, 431, 461, 75, 1, 66],
              "backgroundColor": "#198754"
            }
          ]
        }
      }
    },
    {
      "title": "Albuterol vs. Albuterol/Ipratropium Combo in Bronchiolitis",
      "caption": "Comparison of albuterol-only versus combination therapy (albuterol + ipratropium) utilization among children with bronchiolitis who received β2-agonists.",
      "figure": {
        "tool": "show_chart",
        "params": {
          "type": "bar",
          "title": "Albuterol-Only vs. Albuterol/Ipratropium Among Pediatric Bronchiolitis Patients (≤18 Years)",
          "labels": [
            "Monotherapy: Albuterol MDI 0.09 MG/ACT NDA020503",
            "Monotherapy: Albuterol MDI Generic",
            "Combo: DuoNeb (Alb/Iprat) Neb Soln",
            "Monotherapy: Albuterol Inhal Sol Gen",
            "Combo: Alb/Iprat Soln Nebulizer",
            "Montherapy: Nebulized Albut 5 MG/ml"
          ],
          "datasets": [
            {
              "label": "Exposures (Count)",
              "data": [16776, 4308, 7523, 2596, 119022, 431, 245314],
              "backgroundColor": "#fd7e14"
            }
          ]
        }
      }
    }
  ],
  "footer": "Data from MedCP OMOP-compatible EHR cohort; analysis limited to pediatric patients aged ≤18 years at the time of drug exposure."
}
